  convertHatchBoundaryPaths(A) {
    return A.filter((C) => C.num_segs_or_paths > 0).map((C) => {
      const c = {
        boundaryPathTypeFlag: C.flag
      };
      if (C.flag & 2)
        return {
          ...c,
          hasBulge: C.bulges_present,
          isClosed: C.closed,
          numberOfVertices: C.num_segs_or_paths,
          vertices: C.polyline_paths.map((K) => ({
            x: K.point.x,
            y: K.point.y,
            bulge: K.bulge
          }))
        };
      {
        const K = C.segs.map((H) => {
          if (H.curve_type == kQ.Line)
            return {
              type: HQ.Line,
              start: H.first_endpoint,
              end: H.second_endpoint
            };
          if (H.curve_type == kQ.CircularArc)
            return {
              type: HQ.Circular,
              center: H.center,
              radius: H.radius,
              startAngle: H.start_angle,
              endAngle: H.end_angle,
              isCCW: H.is_ccw
            };
          if (H.curve_type == kQ.EllipticArc)
            return {
              type: HQ.Elliptic,
              center: H.center,
              end: H.endpoint,
              lengthOfMinorAxis: H.minor_major_ratio,
              startAngle: H.start_angle,
              endAngle: H.end_angle,
              isCCW: H.is_ccw
            };
          if (H.curve_type == kQ.Spline)
            return {
              type: HQ.Spline,
              degree: H.degree,
              isRational: H.is_rational,
              isPeriodic: H.is_periodic,
              numberOfKnots: H.num_knots,
              numberOfControlPoints: H.num_control_points,
              knots: H.knots,
              controlPoints: H.control_points,
              numberOfFitData: H.num_fitpts,
              fitDatum: H.fitpts,
              startTangent: H.start_tangent,
              endTangent: H.end_tangent
            };
        });
        return {
          ...c,
          numberOfEdges: C.num_segs_or_paths,
          edges: K
        };
      }
    });
  }
